                            bfs_q.append((nr, nc))
                can_reach_1_4conn[(start_r, start_c)] = found_1

    # Now apply:
    # - 4-connected to 1s + 4-connected to boundary → 2
    # - 4-connected to 1s but not 4-connected to boundary → 3  
    # - not 4-connected to 1s → 0

    result = grid.copy()
    for r in range(rows):
        for c in range(cols):
            if grid[r,c] == 0:
                can_reach_boundary = (r == 0 or r == rows-1 or c == 0 or c == cols-1) or \
                    ((0 <= r < rows and 0 <= c < cols) and 
                     can_4connected_to_boundary(grid, r, c, grid))

                if can_reach_1_4conn.get((r,c), False):
                    if can_reach_boundary:
                        result[r,c] = 2
                    else:
                        result[r,c] = 3
                # else: stays 0

    return result

def can_4connected_to_boundary(grid, sr, sc, grid_vis):
    """Check if sr,sc 0-cell is 4-connected to boundary (via other 0s)"""
    r, c = sr, sc
    queue = deque([(r,c)])
    visited = {(r,c)}

    while queue:
        r, c = queue.popleft()
        on_boundary = (r == 0 or r == grid.shape[0]-1 or c == 0 or c == grid.shape[1]-1)
        if on_boundary:
            return True
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                if (nr, nc) not in visited and grid[nr, nc] == 0:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return False

