def debug_transform(grid_lines):
    grid = np.array([list(map(int, row)) for row in grid_lines], dtype=int)
    print(f"Grid:\n{grid}")

    rows, cols = grid.shape

    # Find 4-connected 0-components
    components = {}
    comp_id = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r,c] == 0 and (r,c) not in components:
                queue = deque([(r,c)])
                comp_cells = [(r,c)]
                components[(r,c)] = comp_id
                while queue:
                    fr, fc = queue.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = fr+dr, fc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and (nr,nc) not in components and grid[nr,nc] == 0:
                            components[(nr, nc)] = comp_id
                            comp_cells.append((nr, nc))
                            queue.append((nr, nc))
                comp_id += 1

    # Find which components touch the boundary
    boundary_comps = set()
    for cid in range(comp_id):
        comp_cells = [(r,c) for (r,c), kid in components.items() if kid == cid]
        is_boundary = any(r == 0 or r == rows-1 or c == 0 or c == cols-1 for r, c in comp_cells)
        if is_boundary:
            boundary_comps.add(cid)

    print(f"boundary_comps: {boundary_comps}")

    # Apply transformation
    result = grid.copy()
    for r in range(rows):
        for c in range(cols):
            if grid[r,c] == 0:
                adj_to_1 = any(
                    0 <= r+dr < rows and 0 <= c+dc < cols and grid[r+dr][c+dc] == 1
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]
                )
                comp_id = components.get((r,c), -1)
                print(f"  ({r},{c}): adj_to_1={adj_to_1}, comp_id={comp_id}, cmp_in_boundary={comp_id in boundary_comps}")
                if adj_to_1:
                    if comp_id in boundary_comps:
                        result[r,c] = 2
                    else:
                        result[r,c] = 3
                # else: stays 0

    return result

